package com.dreamcore.workspace.departure;
import com.dreamcore.workspace.identity.IdentityException;import com.dreamcore.workspace.retention.RetentionClock;
import java.time.Instant;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
/** Bounded bridge into existing durable V20 original/derived cleanup jobs. Never deletes source blobs itself. */
@Service public class DepartureMaterialBridge {
 public record Progress(long discovered,long isolated,long queued,long purged,long failed,long remaining,boolean discoveryComplete,boolean complete){}
 private final JdbcTemplate db;private final RetentionClock clock;public DepartureMaterialBridge(JdbcTemplate db,RetentionClock clock){this.db=db;this.clock=clock;}
 private Map<String,Object> execution(UUID id){var rows=db.queryForList("SELECT * FROM departure_executions WHERE id=?",id);if(rows.isEmpty())throw new IdentityException(404,"DEPARTURE_NOT_FOUND");var e=rows.getFirst();db.queryForList("SELECT id FROM tenants WHERE id=? FOR UPDATE",e.get("tenant_id"));return db.queryForMap("SELECT * FROM departure_executions WHERE id=? FOR UPDATE",id);}
 private Instant time(Map<String,Object>r,String k){return r.get(k)==null?null:((java.sql.Timestamp)r.get(k)).toInstant();}
 private void size(int n){if(n<1||n>100)throw IdentityException.invalid();}
 private List<Map<String,Object>> undiscovered(Map<String,Object>e,int limit){return db.queryForList("""
  SELECT * FROM (
   SELECT 'MATERIAL' AS kind,m.id,m.workspace_id FROM materials m JOIN workspaces w ON w.id=m.workspace_id
    WHERE m.tenant_id=? AND (?::uuid IS NULL OR (w.kind='PERSONAL' AND w.owner_id=?))
    AND NOT EXISTS(SELECT 1 FROM departure_materials d WHERE d.execution_id=? AND d.object_kind='MATERIAL' AND d.object_id=m.id)
   UNION ALL
   SELECT 'FOLDER',f.id,f.workspace_id FROM material_folders f JOIN workspaces w ON w.id=f.workspace_id
    WHERE f.tenant_id=? AND (?::uuid IS NULL OR (w.kind='PERSONAL' AND w.owner_id=?))
    AND NOT EXISTS(SELECT 1 FROM departure_materials d WHERE d.execution_id=? AND d.object_kind='FOLDER' AND d.object_id=f.id)
  ) objects ORDER BY kind,id LIMIT ?
  """,e.get("tenant_id"),e.get("target_account_id"),e.get("target_account_id"),e.get("id"),e.get("tenant_id"),e.get("target_account_id"),e.get("target_account_id"),e.get("id"),limit);}
 @Transactional public Progress isolate(UUID id,int limit){size(limit);var e=execution(id);if(Set.of("CANCELLED","RESTORING","COMPLETE").contains(e.get("state")))return progress(e);if(e.get("kind").equals("TENANT_EXIT")&&clock.now().isBefore(time(e,"deadline")))return progress(e);
  // A cancellation can be interrupted by the fixed deadline: re-isolate any partially restored rows.
  if(!clock.now().isBefore(time(e,"deadline")))for(var o:db.queryForList("SELECT * FROM departure_materials WHERE execution_id=? AND state IN('RESTORED','SKIPPED') ORDER BY object_kind,object_id LIMIT ?",id,limit)){
   var current=db.queryForList("SELECT * FROM content_lifecycle WHERE object_kind=? AND object_id=?",o.get("object_kind"),o.get("object_id"));String state=current.isEmpty()?"ACTIVE":(String)current.getFirst().get("state");
   if(state.equals("ACTIVE"))db.update("UPDATE content_lifecycle SET state='TRASHED',revision=revision+1,changed_at=now(),trashed_at=?,purge_after=? WHERE object_kind=? AND object_id=?",e.get("effective_at"),e.get("deadline"),o.get("object_kind"),o.get("object_id"));
   db.update("UPDATE departure_materials SET state=?,cleanup_job_id=? WHERE execution_id=? AND object_kind=? AND object_id=?",state.equals("PURGED")?"PURGED":state.equals("PURGING")?"QUEUED":"ISOLATED",state.equals("PURGING")?current.getFirst().get("purge_job_id"):null,id,o.get("object_kind"),o.get("object_id"));
  }
  for(var o:undiscovered(e,limit)){String kind=(String)o.get("kind");UUID object=(UUID)o.get("id");var rows=db.queryForList("SELECT * FROM content_lifecycle WHERE object_kind=? AND object_id=?",kind,object);var old=rows.isEmpty()?null:rows.getFirst();String before=old==null?"ACTIVE":(String)old.get("state");Integer applied=null;
   if(before.equals("ACTIVE")){db.update("INSERT INTO content_lifecycle(tenant_id,workspace_id,object_kind,object_id,state,changed_by,trashed_at,purge_after) VALUES (?,?,?,?,'TRASHED',?,?,?) ON CONFLICT(object_kind,object_id) DO UPDATE SET state='TRASHED',revision=content_lifecycle.revision+1,changed_by=EXCLUDED.changed_by,changed_at=EXCLUDED.trashed_at,trashed_at=EXCLUDED.trashed_at,purge_after=EXCLUDED.purge_after,purge_job_id=NULL",e.get("tenant_id"),o.get("workspace_id"),kind,object,e.get("requested_by"),e.get("effective_at"),e.get("deadline"));applied=db.queryForObject("SELECT revision FROM content_lifecycle WHERE object_kind=? AND object_id=?",Integer.class,kind,object);}
   db.update("INSERT INTO departure_materials(execution_id,object_kind,object_id,workspace_id,prior_state,prior_purge_after,applied_revision,cleanup_job_id,state) VALUES (?,?,?,?,?,?,?,?,?)",id,kind,object,o.get("workspace_id"),before,old==null?null:old.get("purge_after"),applied,old==null?null:old.get("purge_job_id"),before.equals("PURGED")?"PURGED":before.equals("PURGING")?"QUEUED":"ISOLATED");
   if(kind.equals("MATERIAL"))db.update("UPDATE knowledge_runs SET status='CANCELLED',warnings='SOURCE_REMOVED',lease_token=NULL,lease_until=NULL,finished_at=now() WHERE material_id=? AND status IN('QUEUED','RUNNING')",object);
  }return progress(e);
 }
 @Transactional public Progress purge(UUID id,int limit){size(limit);var e=execution(id);if(clock.now().isBefore(time(e,"deadline"))||Set.of("CANCELLED","RESTORING").contains(e.get("state")))throw new IdentityException(409,"DEPARTURE_CLEANUP_NOT_DUE");
  sync(id);var rows=db.queryForList("SELECT * FROM departure_materials WHERE execution_id=? AND state IN('ISOLATED','DISCOVERED') ORDER BY object_kind DESC,object_id LIMIT ?",id,limit);for(var o:rows){String kind=(String)o.get("object_kind");UUID object=(UUID)o.get("object_id");var current=db.queryForList("SELECT * FROM content_lifecycle WHERE object_kind=? AND object_id=?",kind,object);if(!current.isEmpty()&&current.getFirst().get("state").equals("PURGED")){db.update("UPDATE departure_materials SET state='PURGED' WHERE execution_id=? AND object_kind=? AND object_id=?",id,kind,object);continue;}
   UUID job;if(!current.isEmpty()&&current.getFirst().get("state").equals("PURGING"))job=(UUID)current.getFirst().get("purge_job_id");else{job=UUID.randomUUID();db.update("INSERT INTO content_cleanup_jobs(id,tenant_id,workspace_id,object_kind,object_id,requested_by,state) VALUES (?,?,?,?,?,?,'QUEUED')",job,e.get("tenant_id"),o.get("workspace_id"),kind,object,e.get("requested_by"));db.update("INSERT INTO content_lifecycle(tenant_id,workspace_id,object_kind,object_id,state,changed_by,purge_job_id) VALUES (?,?,?,?,'PURGING',?,?) ON CONFLICT(object_kind,object_id) DO UPDATE SET state='PURGING',revision=content_lifecycle.revision+1,changed_by=EXCLUDED.changed_by,changed_at=now(),purge_job_id=EXCLUDED.purge_job_id",e.get("tenant_id"),o.get("workspace_id"),kind,object,e.get("requested_by"),job);if(kind.equals("MATERIAL")){db.update("INSERT INTO content_cleanup_materials(job_id,material_id) VALUES (?,?)",job,object);db.update("INSERT INTO content_cleanup_blobs(job_id,object_id) SELECT ?,object_id FROM material_versions WHERE material_id=? GROUP BY object_id",job,object);}}
   db.update("UPDATE departure_materials SET state='QUEUED',cleanup_job_id=? WHERE execution_id=? AND object_kind=? AND object_id=?",job,id,kind,object);
  }return progress(e);
 }
 @Transactional public Progress restore(UUID id,int limit){size(limit);var e=execution(id);if(!e.get("kind").equals("MEMBER_OFFBOARD")||!e.get("state").equals("RESTORING")||!clock.now().isBefore(time(e,"deadline")))throw new IdentityException(409,"DEPARTURE_NOT_RESTORABLE");sync(id);
  for(var o:db.queryForList("SELECT * FROM departure_materials WHERE execution_id=? AND state NOT IN('RESTORED','SKIPPED') ORDER BY object_kind,object_id LIMIT ?",id,limit)){int restored=0;if(o.get("prior_state").equals("ACTIVE")&&o.get("applied_revision")!=null)restored=db.update("UPDATE content_lifecycle SET state='ACTIVE',revision=revision+1,changed_at=now(),trashed_at=NULL,purge_after=NULL,purge_job_id=NULL WHERE object_kind=? AND object_id=? AND state='TRASHED' AND revision=?",o.get("object_kind"),o.get("object_id"),o.get("applied_revision"));db.update("UPDATE departure_materials SET state=? WHERE execution_id=? AND object_kind=? AND object_id=?",restored>0?"RESTORED":"SKIPPED",id,o.get("object_kind"),o.get("object_id"));}return progress(e);
 }
 private void sync(UUID id){db.update("UPDATE departure_materials d SET state='PURGED' FROM content_lifecycle l WHERE d.execution_id=? AND d.object_kind=l.object_kind AND d.object_id=l.object_id AND l.state='PURGED' AND d.state NOT IN('RESTORED','SKIPPED')",id);}
 @Transactional public Progress progress(UUID id){var rows=db.queryForList("SELECT * FROM departure_executions WHERE id=?",id);if(rows.isEmpty())throw new IdentityException(404,"DEPARTURE_NOT_FOUND");return progress(rows.getFirst(),false);}
 private Progress progress(Map<String,Object>e){return progress(e,true);}
 private Progress progress(Map<String,Object>e,boolean reconcile){UUID id=(UUID)e.get("id");if(reconcile)sync(id);var r=db.queryForMap("SELECT count(*) total,count(*) FILTER(WHERE state='ISOLATED') isolated,count(*) FILTER(WHERE state='QUEUED') queued,count(*) FILTER(WHERE state='PURGED') purged,count(*) FILTER(WHERE state NOT IN('PURGED','RESTORED','SKIPPED')) remaining FROM departure_materials WHERE execution_id=?",id);long failed=db.queryForObject("SELECT count(*) FROM departure_materials d JOIN content_cleanup_jobs j ON j.id=d.cleanup_job_id WHERE d.execution_id=? AND j.state='FAILED'",Long.class,id);boolean discovery=undiscovered(e,1).isEmpty();if(e.get("state").equals("RESTORING")){long remaining=db.queryForObject("SELECT count(*) FROM departure_materials WHERE execution_id=? AND state NOT IN('RESTORED','SKIPPED')",Long.class,id);return new Progress((Long)r.get("total"),(Long)r.get("isolated"),(Long)r.get("queued"),(Long)r.get("purged"),failed,remaining,discovery,remaining==0);}long remaining=db.queryForObject("SELECT count(*) FROM departure_materials WHERE execution_id=? AND state<>'PURGED'",Long.class,id);return new Progress((Long)r.get("total"),(Long)r.get("isolated"),(Long)r.get("queued"),(Long)r.get("purged"),failed,remaining,discovery,discovery&&remaining==0&&failed==0);}
}
